tBgpPeerGroupHoldTimeIsStrict = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 14, 3, 3, 1, 63), TruthValue().clone('false')).setMaxAccess("readcreate")
