tBgpPeerNgAdvertiseLdpPrefix = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 14, 4, 10, 1, 14), TruthValue().clone('false')).setMaxAccess("readcreate")
