tBgpPeerNgDampOscErrorInterval = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 14, 4, 10, 1, 36), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(0, 2048)).clone(30)).setUnits('minutes').setMaxAccess("readcreate")
